mapper.select:
/* TimeSaleStoreBensonMapper.getTimeSaleStoreBensonList */
SELECT TO_CHAR(TO_DATE(tsdtd.SALE_DATE, 'yyyymmdd'), 'yyyy-mm-dd') AS SALE_DATE, tsdtd.STORE_CD, tms.STORE_NM,
SUM(CASE WHEN tsdtd.SALE_HOUR = #{item} THEN tsdtd.TOT_SALE_AMT ELSE 0 END) AS TOT_SALE_AMT${item}, SUM(CASE WHEN tsdtd.SALE_HOUR = #{item} THEN tsdtd.REAL_SALE_AMT ELSE 0 END) AS REAL_SALE_AMT${item}, SUM(CASE WHEN tsdtd.SALE_HOUR = #{item} THEN tsdtd.REAL_SALE_CNT ELSE 0 END) AS BILL_CNT${item}
FROM TB_SL_DAILY_TIME_DLVR tsdtd, TB_MS_STORE tms, TB_MS_STORE_INFO tmsi WHERE 1=1 AND tsdtd.HQ_OFFICE_CD = #{hqOfficeCd} AND tsdtd.SALE_DATE BETWEEN #{startDate} AND #{endDate}
AND tsdtd.DLVR_ORDER_FG IN
#{item}
AND tsdtd.STORE_CD IN (${storeCdQuery})
AND tms.HQ_BRAND_CD = #{storeHqBrandCd} -- 매장브랜드 선택일때
-- 매장브랜드 전체일때 AND tms.HQ_BRAND_CD IN
#{item}
AND tms.STORE_CD = tsdtd.STORE_CD AND tmsi.STORE_CD (+)= tms.STORE_CD GROUP BY tsdtd.SALE_DATE, tsdtd.STORE_CD, tms.STORE_NM ORDER BY tsdtd.SALE_DATE, tsdtd.STORE_CD

